// Original camera acceptance candidate: MotionScene -> resolved RenderPlan.
// The image plates are generated by generate_optical_studio_assets.py.
#include "chrononmotion/motion/MotionScene.hpp"
#include "chrononmotion/motion/RenderPlanEmission.hpp"
#include "chrononmotion/motion/RenderPlanLowering.hpp"
#include <chronon3d/render_plan/render_plan.hpp>

#include <cstdlib>
#include <fstream>
#include <iostream>
#include <string>
#include <unordered_map>

using namespace chrononmotion;
using namespace chrononmotion::motion;

int main(int argc, char** argv) try {
    if (argc < 3 || argc > 4) {
        std::cerr << "usage: plan_optical_studio OUTPUT_PLAN ASSET_PREFIX [WIDTH]\n";
        return 2;
    }
    const int width = argc == 4 ? std::atoi(argv[3]) : 1920;
    if (width < 320 || width > 3840 || width % 16 != 0)
        throw std::invalid_argument("width must be a multiple of 16 in [320, 3840]");
    const int height = width * 9 / 16;
    const float s = static_cast<float>(width) / 1920.f;
    constexpr float fps = 30.f;
    constexpr int last = 149;
    const std::string prefix = argv[2];
    MotionScene scene("optical_studio", fps);
    std::unordered_map<std::string, chronon3d::render_plan::LayerPlan> content;
    auto addPlate = [&](int id, const std::string& name, float x, float y, float z,
                        float w, float h) {
        const std::string asset = prefix + "/" + name + ".png";
        auto& layer = scene.addContent(id, name, ContentRef::image(asset, Vector2(w*s, h*s)));
        layer.is3D = true;
        layer.transform.position.set(x*s, y*s, z*s);
        layer.lifetime = FrameRange::between(0, last);
        chronon3d::render_plan::LayerPlan plan;
        plan.type = chronon3d::render_plan::LayerType::Image;
        plan.asset = asset;
        plan.size = {w*s, h*s};
        plan.size_dimensions = 2;
        plan.fit = chronon3d::render_plan::FitMode::Contain;
        content.emplace(std::to_string(id), std::move(plan));
    };
    addPlate(1, "background", 0, 0, -1000, 8400, 4725);
    addPlate(2, "far", 505, 35, -380, 730, 830);
    addPlate(3, "middle", 0, 0, 0, 570, 650);
    addPlate(4, "near", -420, -30, 180, 460, 525);

    auto& parent = scene.addNull(90, "camera_dolly");
    parent.is3D = true;
    parent.tracks.position.add(0.f, Vector3{-95*s, 0, 0}, Easing::easeInOut())
        .add(149.f/fps, Vector3{95*s, 0, 0});
    CameraRig rig(100, 50.f, float(width)/height, 1.f*s, 10000.f*s);
    rig.setParent(90).setPosition({0, 0, 1000*s});
    rig.setFStop(1.4f).setMaxBlur(28*s).setFocusDistance(820*s);
    rig.focusDistanceTrack().add(0.f, 820*s)
        .add(1.2f, 820*s, Easing::easeInOut())
        .add(2.5f, 1000*s, Easing::easeInOut())
        .add(4.f, 1380*s)
        .add(149.f/fps, 1380*s);

    RenderPlanLoweringOptions options;
    options.width = width;
    options.height = height;
    options.jobId = "optical_studio_camera";
    options.schema = chronon3d::render_plan::kRenderPlanSchemaV3;
    options.outputPath = "optical_studio.mp4";
    options.contentLayers = std::move(content);
    options.cameraRig = &rig;
    auto plan = lowerToRenderPlan(scene, options);
    plan.output.format = chronon3d::render_plan::OutputFormat::Mp4;
    plan.output.color_space = "srgb";
    const auto problem = renderPlanEmissionProblem(plan);
    if (!problem.empty()) throw std::runtime_error(problem);
    std::ofstream out(argv[1], std::ios::binary);
    if (!out) throw std::runtime_error("cannot open output plan");
    out << renderPlanToJson(plan) << '\n';
    if (!out) throw std::runtime_error("cannot write output plan");
    std::cout << "optical studio: " << width << 'x' << height << ", "
              << plan.canvas.duration.integral() << " frames\n";
    return 0;
} catch (const std::exception& e) {
    std::cerr << "optical studio: " << e.what() << '\n';
    return 1;
}
